// What the font subsets were cut for, read straight from the blog's sources. run.mjs records
// this in src/fonts/manifest.json; tests/blog-font-subsets-fresh.test.mjs compares it with the
// current sources to say when `npm run fonts:subset` needs rerunning.
import fs from 'node:fs';
import path from 'node:path';

const SOURCE_EXT = new Set(['.md', '.mdx', '.astro', '.ts', '.css', '.json']);
// Generated by the font script itself.
const SKIP = new Set(['src/fonts', 'src/styles/fonts.generated.css']);
const FONT_PROPS = /(?<![\w-])(--font-[\w-]+|font-weight|font-style|font-variant(?:-[a-z]+)?|font-feature-settings|font-variation-settings|font-synthesis(?:-[a-z]+)?|font-family|font-optical-sizing|font|text-transform|hyphens)\s*:\s*([^;{}\n]+)/g;
const LANG_ATTR = /\blang=["']([^"']+)["']/g;

function walk(dir, root, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    const rel = path.relative(root, full).split(path.sep).join('/');
    if (SKIP.has(rel)) continue;
    if (entry.isDirectory()) walk(full, root, out);
    else if (SOURCE_EXT.has(path.extname(entry.name))) out.push(full);
  }
  return out;
}

// Where a declaration applies: the rule's selector, or the tag of an inline style attribute.
// Recording it means moving a declaration to another rule also asks for a rerun.
function context(text, index) {
  const before = text.slice(0, index);
  const tagOpen = before.lastIndexOf('<');
  if (tagOpen > before.lastIndexOf('>')) return before.slice(tagOpen).replace(/\s+/g, ' ').replace(/ ?style=["'{]*$/, '').slice(0, 120);
  const open = before.lastIndexOf('{');
  if (open < 0 || open < before.lastIndexOf('}')) return '';
  const start = Math.max(before.lastIndexOf('}', open), before.lastIndexOf(';', open), before.lastIndexOf('*/', open) + 1) + 1;
  return before.slice(start, open).replace(/\/\*[\s\S]*?\*\//g, '').replace(/\s+/g, ' ').trim().slice(-160);
}

export function blogFontInputs(blogRoot) {
  const files = walk(path.join(blogRoot, 'src'), blogRoot, []);
  // Base.astro renders product facts (CTA labels) on every page.
  files.push(path.join(blogRoot, '..', 'shared', 'product-facts.generated.json'));
  const chars = new Set();
  const declarations = new Set();
  const langs = new Set(['en']);
  for (const file of files) {
    const text = fs.readFileSync(file, 'utf8');
    for (const ch of text) {
      if (ch.codePointAt(0) > 0x7e && !/\s/u.test(ch)) chars.add(ch);
    }
    if (/\.(css|astro|md|mdx)$/.test(file)) {
      const rel = path.relative(blogRoot, file).split(path.sep).join('/');
      for (const m of text.matchAll(FONT_PROPS)) {
        const [, prop, value] = m;
        const decl = `${prop}: ${value.trim().replace(/["'`]+(\s*\/?>.*)?$/, '').replace(/\s+/g, ' ').toLowerCase()}`;
        declarations.add(`${rel} | ${context(text, m.index)} | ${decl}`);
      }
      for (const [, lang] of text.matchAll(LANG_ATTR)) langs.add(lang.split('-')[0].toLowerCase());
    }
  }
  const sortCp = (a, b) => a.codePointAt(0) - b.codePointAt(0);
  return {
    chars: [...chars].sort(sortCp).join(''),
    declarations: [...declarations].sort(),
    langs: [...langs].sort(),
  };
}
